parameters.jsCode:
// --- CÓDIGO PARA O SUB-FLUXO QUE BUSCA O CARDÁPIO (LISTA SIMPLES) ---

const inputParams = $items("Start")[0].json;
const paginaAtual = parseInt(inputParams.pagina, 10) || 1;
const tipoSelecionado = inputParams.tipo;

// Define quantos itens por página (Bebidas e Individuais mostram mais itens por vez)
let itensPorPagina = (tipoSelecionado === 'Individuais' || tipoSelecionado === 'Bebidas') ? 50 : 10;

let itensOrdenados;
let mapaId;

// 1. Lógica de Cache (igual à anterior)
if (paginaAtual > 1 && inputParams.itens_ordenados_cache) {
    try {
        itensOrdenados = JSON.parse(inputParams.itens_ordenados_cache);
    } catch(e) {
        itensOrdenados = [];
    }
    mapaId = (inputParams.mapa_id_json) ? JSON.parse(inputParams.mapa_id_json) : {};
} else {
    // CACHE MISS (Página 1) - Busca e Processa
    const todosItens = $input.all();

    // Filtra pelo tipo principal (ex: "Individuais", "Bebidas") e estoque > 0
    const itensFiltrados = todosItens
        .map(item => item.json)
        .filter(item =>
            parseInt(item.property_estoque, 10) > 0 &&
            item.property_tipo === tipoSelecionado
        );

    // Ordena: Em ordem numérica crescente pelo índice do item
    itensOrdenados = itensFiltrados.sort((a, b) => {
        const indiceA = parseInt(a.property_ndice, 10) || 0;
        const indiceB = parseInt(b.property_ndice, 10) || 0;

        return indiceA - indiceB;
    });

    mapaId = {};
}

// 2. Paginação
const startIndex = (paginaAtual - 1) * itensPorPagina;
const itensDaPagina = itensOrdenados.slice(startIndex, startIndex + itensPorPagina);

// 3. Constrói o Cabeçalho Personalizado
let menuTexto = "";
if (paginaAtual === 1) {
    // Adiciona o cabeçalho personalizado com o nome do cliente
    menuTexto += `_*👸🏾 Kakaw - TheLordTrufas.*_\n\n`;
    menuTexto += `_*${inputParams.primeiro_nome}*_, Aqui estão as\n`;

    // Altera o texto dependendo do tipo selecionado
    if (tipoSelecionado === 'Individuais') {
        menuTexto += `*Trufas de Colher* disponíveis hoje\nna categoria (🍫 *Individuais*):\n\n`;
    } else if (tipoSelecionado === 'Bebidas') {
        menuTexto += `*Bebidas* geladinhas disponíveis hoje\nna categoria (🥤 *Bebidas*):\n\n`;
    } else {
        // Combos ou outros
        menuTexto += `*Opções* disponíveis hoje\nna categoria (📦 *Combos*):\n\n`;
    }
} else {
    menuTexto += `Aqui está a continuação\ndo cardápio na categoria *${tipoSelecionado}*:\n\n`;
}

// 4. Lógica de Formatação (Lista Direta)
for (const item of itensDaPagina) {

    // --- FORMATAÇÃO DO ITEM ---
    const preco = parseFloat(item.property_pre_o).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const preco_promo = parseFloat(item.property_pre_o_promo).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const indiceDoItem = item.property_ndice;

    if (!indiceDoItem) continue;

    let linhaDoMenu = `*${indiceDoItem})*\u200B`;

    // Ícone dinâmico do item (Presente, Chocolate, Bebida ou Combo)
    if (item.property_em_promo) {
        linhaDoMenu += ` 🎁`;
    } else if (tipoSelecionado === 'Bebidas') {
        linhaDoMenu += ` 🥤`;
    } else {
        linhaDoMenu += (tipoSelecionado === 'Individuais') ? ` 🍫` : ` 📦`;
    }

    linhaDoMenu += ` ${item.property_nome}`;

    // (Opcional) Adiciona o peso/medida se disponível (ex: 350ml para bebidas)
    if (item.property_medida) {
         linhaDoMenu += ` (${item.property_medida})`;
    }

    linhaDoMenu += `\n_*Preço:*_ `;

    if (item.property_em_promo) {
        linhaDoMenu += `~${preco}~ *${preco_promo}*`;
    } else {
        linhaDoMenu += `*${preco}*`;
    }

    if (item.property_descri_o && item.property_descri_o.trim()) {
        linhaDoMenu += `\n_*Descrição:*_\n_${item.property_descri_o.trim()}_`;
    }

    // Adiciona a linha e um separador limpo no final
    menuTexto += linhaDoMenu + `\n\n----------------------------------------------------------\n\n`;

    // Constrói o mapa cumulativo
    let precoFinalParaMapa = (parseFloat(item.property_pre_o_promo) > 0) ? parseFloat(item.property_pre_o_promo) : parseFloat(item.property_pre_o);

    mapaId[indiceDoItem] = {
        id: item.property_id,
        nome: item.property_nome,
        preco: precoFinalParaMapa,
        estq: item.property_estoque
    };
}

menuTexto += `ㅤ`; 


// 6. Verifica se ainda existem mais itens
const tem_mais_itens = (startIndex + itensPorPagina) < itensOrdenados.length;

if (itensDaPagina.length === 0) {
    menuTexto = (paginaAtual === 1)
        ? `🚫 Desculpe, não temos nenhum item disponível na categoria *${tipoSelecionado}* no momento.`
        : "Não há mais itens para mostrar.";
}

// 7. Retorna o resultado
const resultado = {
    menu_formatado: menuTexto,
    mapa_id_json: JSON.stringify(mapaId),
    itens_ordenados_cache: JSON.stringify(itensOrdenados),
    tem_mais_itens: tem_mais_itens,
    Jid: inputParams.Jid,
    telefone_real: inputParams.telefone_real,
    primeiro_nome: inputParams.primeiro_nome,
    pagina: inputParams.pagina,
    tipo: tipoSelecionado
};

return [{ json: resultado }];
